package main

import (
	"bytes"
	"compress/zlib"
	"encoding/base64"
	"io"
	"strings"
)

// The owner's orb is assets/orb-online-green-refined.gif, sampled onto a square
// dot raster. This file is generated by tools/mkorb.py, which the Windows
// workflow runs before it tests and builds, so every shipped dot and both green
// shades are the GIF's own pixels. The empty placeholder below keeps a bare
// checkout compiling until that step runs.
const (
	orbRaster = 152

	orbGreenDim    = 0x35a373
	orbGreenBright = 0x6cf3b3

	orbFramesB64 = ``
)

var (
	orbDelays = []int{}

	orbFrames = decodeOrbFrames()
)

func decodeOrbFrames() [][]uint8 {
	joined := strings.ReplaceAll(orbFramesB64, "\n", "")
	if joined == "" {
		return nil
	}
	packed, err := base64.StdEncoding.DecodeString(joined)
	if err != nil {
		return nil
	}
	reader, err := zlib.NewReader(bytes.NewReader(packed))
	if err != nil {
		return nil
	}
	defer reader.Close()
	all, err := io.ReadAll(reader)
	if err != nil {
		return nil
	}
	size := orbRaster * orbRaster
	perFrame := (size + 3) / 4
	if perFrame == 0 || len(all)%perFrame != 0 {
		return nil
	}
	frames := make([][]uint8, 0, len(all)/perFrame)
	for offset := 0; offset+perFrame <= len(all); offset += perFrame {
		levels := make([]uint8, size)
		for index := 0; index < size; index++ {
			levels[index] = (all[offset+index/4] >> (2 * uint(index%4))) & 0x3
		}
		frames = append(frames, levels)
	}
	return frames
}
